    channel: vi.fn().mockReturnValue({
      on: vi.fn().mockReturnThis(),
      subscribe: vi.fn(),
    }),
    removeChannel: vi.fn(),
  },
}));

// Mock de toast (importado diretamente no componente, não via hook)
vi.mock('@/shared/hooks/use-toast', () => ({
  toast: vi.fn(),
  useToast: () => ({ toast: vi.fn() }),
}));

// ── helpers ───────────────────────────────────────────────────────────────────

/** Dados simulados: 3 lançamentos "Brownie", 2 lançamentos "brigadeiro" */
const MOCK_PAGE_1 = [
  { product_name: 'Brownie' },
  { product_name: 'Brownie' },
  { product_name: 'Brownie' },
  { product_name: 'brigadeiro' },
  { product_name: 'brigadeiro' },
