/**
 * Testes co-located — PadronizarNomesProducaoButton
 *
 * Cobre:
 *  1. Smoke: botão "Padronizar nomes" renderiza.
 *  2. Abre + lista: ao clicar, dialog abre e mostra nomes distintos com contagem.
 *  3. Rename simples (sem colisão): Enter → update({ product_name }) e eq chamados;
 *     objeto passado ao update contém SOMENTE product_name.
 *  4. Aviso de fusão: editar para nome existente → AlertDialog aparece e update
 *     NÃO é chamado antes de confirmar "Fundir".
 */
import { render, screen, waitFor, act, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { PadronizarNomesProducaoButton } from './PadronizarNomesProducaoButton';
import { supabase } from '@/integrations/supabase/client';

// ── re-mock do Supabase (sobrescreve o global de setup.ts) ────────────────────
// Precisamos de controle total sobre from().select().range().returns() e
// from().update().eq() para cada caso de teste.
vi.mock('@/integrations/supabase/client', () => ({
  supabase: {
    from: vi.fn(),
    rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
    auth: {
      getUser: vi.fn().mockResolvedValue({ data: { user: null }, error: null }),
      getSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
      onAuthStateChange: vi.fn(() => ({
        data: { subscription: { unsubscribe: vi.fn() } },
      })),
    },
    channel: vi.fn().mockReturnValue({
      on: vi.fn().mockReturnThis(),
      subscribe: vi.fn(),
    }),
    removeChannel: vi.fn(),
  },
}));

// Mock de toast (importado diretamente no componente, não via hook)
vi.mock('@/shared/hooks/use-toast', () => ({
  toast: vi.fn(),
  useToast: () => ({ toast: vi.fn() }),
}));

// ── helpers ───────────────────────────────────────────────────────────────────

/** Dados simulados: 3 lançamentos "Brownie", 2 lançamentos "brigadeiro" */
const MOCK_PAGE_1 = [
  { product_name: 'Brownie' },
  { product_name: 'Brownie' },
  { product_name: 'Brownie' },
  { product_name: 'brigadeiro' },
  { product_name: 'brigadeiro' },
];

/**
 * Cria uma chain thenable que resolve com `resolveValue`.
 *
 * O componente faz:
 *   const { data, error } = await supabase.from(...).select(...).range(...).returns<>()
 *
 * `await` chama `.then` no objeto retornado por `.returns()`.
 * Para que o await funcione corretamente, `.then` deve respeitar o protocolo
 * Promise/A+ — receber (onFulfilled, onRejected) e retornar uma Promise.
 * Usamos Promise.resolve(resolveValue).then como implementação.
 */
function makeSelectChain(resolveValue: { data: unknown; error: null | { message: string } }) {
  const thenable = {
    then: (
      onFulfilled?: ((v: { data: unknown; error: null | { message: string } }) => unknown) | null,
      onRejected?: ((e: unknown) => unknown) | null,
    ) => Promise.resolve(resolveValue).then(onFulfilled ?? undefined, onRejected ?? undefined),
  };

  const chain: Record<string, unknown> = {
    select: vi.fn(),
    range: vi.fn(),
    returns: vi.fn(),
    ...thenable,
  };

  // Cada método retorna o mesmo objeto (chain) para que a sequência encadeada
  // termine sempre no mesmo thenable.
  (chain['select'] as ReturnType<typeof vi.fn>).mockReturnValue(chain);
  (chain['range'] as ReturnType<typeof vi.fn>).mockReturnValue(chain);
  (chain['returns'] as ReturnType<typeof vi.fn>).mockReturnValue(chain);

  return chain;
}

/**
 * Cria uma chain para update().eq() que resolve com `resolveValue`.
 */
function makeUpdateChain(resolveValue: { error: null | { message: string } }) {
  const eqFn = vi.fn().mockResolvedValue(resolveValue);
  const updateFn = vi.fn().mockReturnValue({ eq: eqFn });
  return { updateFn, eqFn };
}

function renderWithProviders(ui: React.ReactElement) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false },
    },
  });
  return render(<QueryClientProvider client={queryClient}>{ui}</QueryClientProvider>);
}

// ── testes ────────────────────────────────────────────────────────────────────

describe('PadronizarNomesProducaoButton', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ── Caso 1: Smoke ──────────────────────────────────────────────────────────
  it('1. renderiza o botão "Padronizar nomes"', () => {
    // Neste caso o dialog não abre, então o from() não é chamado.
    renderWithProviders(<PadronizarNomesProducaoButton />);

    const btn = screen.getByRole('button', { name: /padronizar nomes/i });
    expect(btn).toBeInTheDocument();
  });

  // ── Caso 2: Abre + lista ───────────────────────────────────────────────────
  it('2. ao clicar no botão, o dialog abre e exibe nomes com contagem', async () => {
    // Primeira chamada: retorna MOCK_PAGE_1 (< 1000 itens → para paginação)
    // Segunda chamada em diante: retorna [] (fim dos dados)
    let callCount = 0;
    (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(() => {
      callCount++;
      const data = callCount === 1 ? MOCK_PAGE_1 : [];
      return makeSelectChain({ data, error: null });
    });

    renderWithProviders(<PadronizarNomesProducaoButton />);

    const btn = screen.getByRole('button', { name: /padronizar nomes/i });
    await act(async () => {
      fireEvent.click(btn);
    });

    // Dialog deve aparecer com os nomes como valores de input (o componente usa <Input value={name}>)
    await waitFor(() => {
      expect(screen.getByDisplayValue('Brownie')).toBeInTheDocument();
    });

    expect(screen.getByDisplayValue('brigadeiro')).toBeInTheDocument();

    // Verificar contagens (renderizadas como badges de texto)
    expect(screen.getByText('3 lanç.')).toBeInTheDocument();
    expect(screen.getByText('2 lanç.')).toBeInTheDocument();
  });

  // ── Caso 3: Rename simples (sem colisão) ───────────────────────────────────
  it('3. Enter no input chama update({ product_name }) e eq; update recebe SOMENTE product_name', async () => {
    let selectCallCount = 0;
    const { updateFn, eqFn } = makeUpdateChain({ error: null });

    (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(() => {
      selectCallCount++;
      // Primeira passagem retorna dados; re-fetch após update retorna lista vazia
      const data = selectCallCount === 1 ? MOCK_PAGE_1 : [];
      const selectChain = makeSelectChain({ data, error: null });
      // Injetar update na chain do from()
      (selectChain as Record<string, unknown>)['update'] = updateFn;
      return selectChain;
    });

    renderWithProviders(<PadronizarNomesProducaoButton />);

    // Abrir dialog
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /padronizar nomes/i }));
    });

    await waitFor(() => {
      expect(screen.getByDisplayValue('Brownie')).toBeInTheDocument();
    });

    // Encontrar o input do item "Brownie" e alterar o valor
    const input = screen.getByDisplayValue('Brownie');
    await act(async () => {
      await userEvent.clear(input);
      await userEvent.type(input, 'Brownie Vegano');
    });

    // Pressionar Enter para salvar
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter', code: 'Enter' });
    });

    // Aguardar que update e eq sejam chamados
    await waitFor(() => {
      expect(updateFn).toHaveBeenCalledTimes(1);
    });

    // CRÍTICO: objeto passado ao update deve conter SOMENTE product_name
    const updateArg = updateFn.mock.calls[0][0] as Record<string, unknown>;
    expect(Object.keys(updateArg)).toEqual(['product_name']);
    expect(updateArg['product_name']).toBe('Brownie Vegano');

    // eq deve ter sido chamado com o nome original
    expect(eqFn).toHaveBeenCalledWith('product_name', 'Brownie');
  });

  // ── Caso 4: Aviso de fusão (AlertDialog) ───────────────────────────────────
  it('4. renomear para nome já existente exibe AlertDialog de fusão; update NÃO é chamado antes de confirmar', async () => {
    let selectCallCount = 0;
    const { updateFn } = makeUpdateChain({ error: null });

    (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(() => {
      selectCallCount++;
      const data = selectCallCount === 1 ? MOCK_PAGE_1 : [];
      const selectChain = makeSelectChain({ data, error: null });
      (selectChain as Record<string, unknown>)['update'] = updateFn;
      return selectChain;
    });

    renderWithProviders(<PadronizarNomesProducaoButton />);

    // Abrir dialog
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /padronizar nomes/i }));
    });

    await waitFor(() => {
      expect(screen.getByDisplayValue('Brownie')).toBeInTheDocument();
    });

    // Renomear "Brownie" para "brigadeiro" (nome que já existe na lista)
    const input = screen.getByDisplayValue('Brownie');
    await act(async () => {
      await userEvent.clear(input);
      await userEvent.type(input, 'brigadeiro');
    });

    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter', code: 'Enter' });
    });

    // AlertDialog de confirmação de fusão deve aparecer
    await waitFor(() => {
      expect(screen.getByText(/confirmar fus[aã]o de itens/i)).toBeInTheDocument();
    });

    // update NÃO deve ter sido chamado ainda
    expect(updateFn).not.toHaveBeenCalled();

    // Verificar que o botão "Fundir" está presente
    expect(screen.getByRole('button', { name: /fundir/i })).toBeInTheDocument();
  });
});
